package com.tuap.backend.servicios;
import java.time.*; import java.util.*; import org.slf4j.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.beans.factory.annotation.Autowired;
import com.tuap.backend.config.CleanupProperties; import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
@Service public class CleanupService {
 private static final Logger log=LoggerFactory.getLogger(CleanupService.class); private final RefreshTokenDAO refresh; private final PasswordResetTokenDAO resets; private final UploadedFileDAO uploads; private final MensajeDAO messages; private final ClienteDAO clients; private final EntrenadorDAO trainers; private final FileStorageService storage; private final CleanupProperties properties; private final Clock clock;
 @Autowired public CleanupService(RefreshTokenDAO r,PasswordResetTokenDAO p,UploadedFileDAO u,MensajeDAO m,ClienteDAO c,EntrenadorDAO t,FileStorageService s,CleanupProperties x){this(r,p,u,m,c,t,s,x,Clock.systemUTC());}
 CleanupService(RefreshTokenDAO r,PasswordResetTokenDAO p,UploadedFileDAO u,MensajeDAO m,ClienteDAO c,EntrenadorDAO t,FileStorageService s,CleanupProperties x,Clock k){refresh=r;resets=p;uploads=u;messages=m;clients=c;trainers=t;storage=s;properties=x;clock=k;}
 @Transactional public int cleanupRefreshTokens(){Instant cutoff=Instant.now(clock).minus(Duration.ofDays(properties.getRefreshRetentionDays())); List<RefreshToken> old=refresh.findAll().stream().filter(t -> !t.isActiveAt(Instant.now(clock)) && (t.getExpiresAt().isBefore(cutoff) || (t.getRevokedAt()!=null && t.getRevokedAt().isBefore(cutoff)) || (t.getRotatedAt()!=null && t.getRotatedAt().isBefore(cutoff)))).toList();refresh.deleteAll(old);log.info("cleanup refresh: {}",old.size());return old.size();}
 @Transactional public int cleanupPasswordResetTokens(){Instant cutoff=Instant.now(clock).minus(Duration.ofDays(properties.getPasswordResetRetentionDays())); List<PasswordResetToken> old=resets.findAll().stream().filter(t -> !t.isUsableAt(Instant.now(clock)) && (t.getExpiresAt().isBefore(cutoff) || (t.getUsedAt()!=null && t.getUsedAt().isBefore(cutoff)))).toList();resets.deleteAll(old);log.info("cleanup reset: {}",old.size());return old.size();}
 @Transactional public int cleanupOrphanProfileImages(){return cleanupOrphans(UploadPurpose.PROFILE_IMAGE);}
 @Transactional public int cleanupOrphanChatAttachments(){return cleanupOrphans(UploadPurpose.CHAT_ATTACHMENT);}
 private int cleanupOrphans(UploadPurpose purpose){Instant cutoff=Instant.now(clock).minus(Duration.ofHours(properties.getOrphanUploadGraceHours()));int removed=0;for(UploadedFile file:uploads.findAll()){if(file.getPurpose()!=purpose||!file.getCreatedAt().isBefore(cutoff)||referenced(file))continue;try{storage.delete(file.getStorageKey());uploads.delete(file);removed++;}catch(RuntimeException ex){log.warn("cleanup orphan upload failed for metadata id {}",file.getId());}}log.info("cleanup orphan uploads {}: {}",purpose,removed);return removed;}
 private boolean referenced(UploadedFile f){if(f.getPurpose()==UploadPurpose.CHAT_ATTACHMENT)return messages.existsByAttachmentId(f.getId());String url="/api/upload/files/"+f.getId();return clients.findAll().stream().anyMatch(c->url.equals(c.getFotoPerfil()))||trainers.findAll().stream().anyMatch(t->url.equals(t.getFotoPerfil()));}
 public CleanupResult cleanupAll(){return new CleanupResult(cleanupRefreshTokens(),cleanupPasswordResetTokens(),cleanupOrphanProfileImages(),cleanupOrphanChatAttachments());}
 public record CleanupResult(int refreshTokens,int passwordResetTokens,int profileImages,int chatAttachments){}
}
